// patchgen rewrites the constructor functions in generated step builder files
// to accept an optional major version argument.
//
// This is a one-time migration tool. After running it, cmd/stepgen will
// generate new files with the updated constructor signature automatically
// because the template was updated alongside this tool.
//
// Before (generated by the old template):
//
//	func GitClone() *GitCloneBuilder {
//		return &GitCloneBuilder{Builder: From("git-clone", "8")}
//	}
//
// After:
//
//	func GitClone(version ...string) *GitCloneBuilder {
//		v := "8"
//		if len(version) > 0 && version[0] != "" {
//			v = version[0]
//		}
//		return &GitCloneBuilder{Builder: From("git-clone", v)}
//	}
//
// Usage:
//
//	go run ./cmd/patchgen [--step-dir=step]
package main

import (
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"regexp"
)

// constructorRe matches a zero-argument typed step constructor and captures:
//
//	$1 — function name   (e.g. GitClone)
//	$2 — return type     (e.g. GitCloneBuilder)
//	$3 — step ID         (e.g. git-clone)
//	$4 — major version   (e.g. 8)
var constructorRe = regexp.MustCompile(
	`func (\w+)\(\) \*(\w+Builder) \{\n` +
		`\treturn &\w+Builder\{Builder: From\("([^"]+)", "([^"]+)"\)\}\n` +
		`\}`,
)

const constructorRepl = `func $1(version ...string) *$2 {
	v := "$4"
	if len(version) > 0 && version[0] != "" {
		v = version[0]
	}
	return &$2{Builder: From("$3", v)}
}`

func main() {
	stepDir := flag.String("step-dir", "step", "directory containing gen_*.go builder files")
	flag.Parse()

	paths, err := filepath.Glob(filepath.Join(*stepDir, "gen_*.go"))
	if err != nil || len(paths) == 0 {
		fatalf("no gen_*.go files found in %s", *stepDir)
	}

	updated, skipped := 0, 0
	for _, p := range paths {
		changed, err := patchFile(p)
		if err != nil {
			fatalf("patch %s: %v", p, err)
		}
		if changed {
			updated++
		} else {
			skipped++
		}
	}
	fmt.Printf("done: %d files updated, %d already up to date\n", updated, skipped)
}

// patchFile rewrites the constructor in path if it still uses the old zero-arg
// signature. Returns true if the file was modified.
func patchFile(path string) (bool, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}

	patched := constructorRe.ReplaceAll(src, []byte(constructorRepl))
	if string(patched) == string(src) {
		return false, nil // already up to date
	}

	// Validate the result compiles before writing.
	formatted, err := format.Source(patched)
	if err != nil {
		return false, fmt.Errorf("gofmt after patch: %w", err)
	}

	if err := os.WriteFile(path, formatted, 0644); err != nil {
		return false, err
	}
	return true, nil
}

func fatalf(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "patchgen: "+format+"\n", args...)
	os.Exit(1)
}
